// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge as C} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    C c;
    Attacker attacker;

    function setUp() public {
        // deploy reference contract (constructor requires 1 ether)
        c = new C{value: 1 ether}();
        // deploy attacker who will revert on receive
        attacker = new Attacker();
    }

    // fuzz parameters: the block offset where the guess is locked (1..10)
    // and a bytes32 guess value (the fuzzer will search for values triggering difference)
    function testFuzz_property(uint8 blockOffset, bytes32 guess) public {
        // admissible domain: blockOffset should be at least 1 and not huge
        vm.assume(blockOffset >= 1 && blockOffset <= 10);

        address user = address(this);

        // fund the attacker so it can be used as msg.sender in lockInGuess
        vm.deal(user, 2 ether);

        // Lock in a guess paying 1 ether as the calling account
        // use prank to make the call from this contract (an EOA-like account simulated by vm)
        vm.prank(user);
        c.lockInGuess{value: 1 ether}(guess);

        // advance to the block where settle should be allowed (block > locked.block)
        // The contract stores block.number + 1 when locking; we advanced blockOffset blocks
        // We warp/roll forward by blockOffset to ensure block.number > stored block
        // Use vm.roll to increment block.number
        uint256 targetRoll = block.number + blockOffset;
        vm.roll(targetRoll);

        // Now, we want the transfer to the caller to FAIL so the mutant's deferred-zeroing leaves state set.
        // To simulate transfer failing, we call settle via an attacker contract that reverts on receive.
        // But settle pays to msg.sender (the caller). So we need to have the attacker be the caller
        // who originally locked the guess. Therefore, we must have the attacker perform lockInGuess earlier.
        // Re-deploy/setup: do the lockInGuess from attacker instead. So redo with attacker as caller.

        // Reset state: deploy fresh C and attacker to ensure consistent initial conditions
        c = new C{value: 1 ether}();
        attacker = new Attacker();

        // fund attacker
        vm.deal(address(attacker), 2 ether);

        // attacker locks in guess paying 1 ether
        attacker.lockIn(c, guess);

        // advance blocks so settle is allowed
        vm.roll(block.number + blockOffset);

        // Now call settle from attacker; this will invoke attacker.receive and revert there.
        bool ok;
        try attacker.callSettle(c) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property: after such a failing transfer, the reference contract guarantees
        // that guesses[attacker].block == 0. We observe this by calling settle again from attacker;
        // if guesses[attacker].block is zero, settle() will revert because require(guesses[msg.sender].block != 0)
        // and the call will revert immediately. If the mutant left block non-zero, calling settle a second
        // time would attempt to compute answer and (again) attempt transfer which will revert in attacker, i.e.
        // it would not revert due to the require about block!=0. We therefore test that calling settle now reverts
        // immediately on the reference (indicating block==0). We capture that by trying to call settle and expecting revert.

        bool secondOk;
        try attacker.callSettle(c) {
            secondOk = true;
        } catch {
            secondOk = false;
        }

        // The single assert: on the reference contract, after the failed transfer the stored block for attacker
        // is cleared, so a subsequent settle call should REVERT (secondOk == false). The mutant may leave it set
        // and thus secondOk might be false for a different reason, but importantly there exists some inputs where
        // the mutant would allow second settle to proceed; the fuzzer can find those. We assert the property the
        // reference must always satisfy: second settle call reverts (i.e., secondOk == false).
        assertTrue(!secondOk);
    }
}

// Minimal attacker contract which reverts on receive and provides helper wrappers
contract Attacker {
    // accept nothing; revert on receive to simulate a failing payout
    receive() external payable {
        revert("no funds");
    }

    function lockIn(C c, bytes32 guess) external payable {
        // send 1 ether from this contract's balance
        c.lockInGuess{value: 1 ether}(guess);
    }

    function callSettle(C c) external {
        c.settle();
    }
}
